// FMI interface variables (value references)

#define FMI_INPUT_T 1
#define FMI_OUTPUT_P 2
#define FMI_PARA_T_limit 3
#define FMI_PARA_k_P 4

/*! Holds a copy of all published FMI variables.
	Use P_Control::readFMIVariables() to populate the struct with the current values, and
	P_Control::writeFMIVariables() to store the computed values (outputs, calculated parameters and
	local variables) back into the FMU.
*/
struct FMIVariables {
	double T; // input
	double P; // output
	double T_limit; // parameter
	double k_P; // parameter
};

// Helper macros for (de-)serialization of the FMU state, can be used in the user-defined functions
// P_Control::serializeUserState() and P_Control::deserializeUserState().

// macro for storing a POD and increasing the pointer to the linear memory array
#define SERIALIZE(type, storageDataPtr, value)\
{\
  *reinterpret_cast<type *>(storageDataPtr) = (value);\
  (storageDataPtr) = reinterpret_cast<char *>(storageDataPtr) + sizeof(type);\
}

// macro for retrieving a POD and increasing the pointer to the linear memory array
#define DESERIALIZE(type, storageDataPtr, value)\
{\
  (value) = *reinterpret_cast<type *>(storageDataPtr);\
  (storageDataPtr) = reinterpret_cast<const char *>(storageDataPtr) + sizeof(type);\
}

#endif // P_Control_generatedH
